       COUNT(CASE WHEN status = 'done' THEN 1 END)
FROM orders;

-- 입력 데이터 전체 (SQLite)
-- CREATE TABLE pairs(id INTEGER, a INTEGER, b INTEGER);
-- INSERT INTO pairs VALUES(1,1,1),(2,NULL,NULL),(3,NULL,1),(4,1,NULL);
SELECT id FROM pairs WHERE a IS b ORDER BY id;

-- 입력 데이터 전체 (SQLite)
-- CREATE TABLE people(id INTEGER, team TEXT);
-- INSERT INTO people VALUES(1,'A'),(2,'A'),(3,'B');
SELECT a.id, b.id
FROM people AS a
JOIN people AS b ON a.team = b.team
WHERE a.id < b.id
ORDER BY a.id, b.id;

-- 입력 데이터 전체 (SQLite)
-- CREATE TABLE sales(id INTEGER, amount INTEGER);
-- INSERT INTO sales VALUES(3,3),(1,2),(2,5);
SELECT SUM(amount) OVER (
    ORDER BY id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW
)
FROM sales ORDER BY id;

-- 입력 데이터 전체 (SQLite)
-- CREATE TABLE orders(id INTEGER, amount INTEGER);
-- INSERT INTO orders VALUES(1,50),(2,90),(3,90),(4,10);
SELECT id FROM orders
ORDER BY amount DESC, id ASC
LIMIT 2 OFFSET 1;

-- 입력 데이터 전체 (SQLite)
-- CREATE TABLE measures(id INTEGER, amount REAL, base REAL);
-- INSERT INTO measures VALUES(1,10,2),(2,0,0),(3,9,NULL);
SELECT COALESCE(amount / NULLIF(base, 0), -1)
FROM measures ORDER BY id;

-- 입력 데이터 전체 (SQLite)
